const cds = require('../../bin/cds');
const { bold } = require('../../lib/util/term');
const completionFs = require('./completionFs');
const completionSetup = require('../../lib/init/template/completion/completionSetup');

// Sentinel factories — returned by staticCompletions() to mark special argument types.
const FILE  = (exts, { dirs } = {}) => exts ? { type: ':file', ext: exts.split(',').map(e => e.trim()), dirs: dirs ?? false } : ':file';
const DIR   = () => ':dir';
const COMMA = (values) => ({ type: ':comma', values });

// The '_' key in a staticCompletions map marks the default positional argument.
const POSITIONAL_KEY = '_';

const isFileSentinel = s => s === ':file' || s === ':dir' || (s?.type === ':file' && Array.isArray(s.ext));
const fileRegex      = s => s.ext ? new RegExp(`\\.(${s.ext.join('|')})$`) : null;
const filePs1        = s => s.ext ? (s.dirs ? `':file+dir:${s.ext.join(',')}'` : `':file:${s.ext.join(',')}'`) : `'${s}'`;

module.exports = Object.assign(completion, {
    staticCompletions: () => ({ '--shell': completionSetup.supportedShells }),
    FILE,
    DIR,
    COMMA,
    // Exposed for the build-time script generator
    buildCompletionMap,
    filePs1,
    POSITIONAL_KEY,
    options: ['--shell', '--curr', '--line', '--prev'],
    shortcuts: ['-s'],
    flags: ['--add', '--profile', '--remove'],
    help: `
# SYNOPSIS

    *cds completion* <options>

    Adds or removes shell completion for cds commands. Currently supported shells:
        Bash, fish, Git Bash, Zsh, and PowerShell.

    Depending on the operating system and the shell type, the following files will be changed:
        Linux, WSL
            Bash: ~/.bashrc
            fish: ~/.config/fish/config.fish
            Zsh: ~/.zshrc
        macOS
            Bash: ~/.bash_profile
            fish: ~/.config/fish/config.fish
            Zsh: ~/.zshrc
        Windows
            PowerShell: $PROFILE
            Git Bash: ~/.bash_profile

    This command also acts as an internal completion handler for the shell completion scripts.

# OPTIONS

     *--add*
        Add shell completion for cds commands (see examples).

    *--remove*
        Remove shell completion for cds commands (see examples).

    *--profile* _(deprecated)_
        Print the path to the completion script for the given shell.

    *--shell* <bash | fish | gitbash | ps | zsh>
        Force the shell completion code to be added to the correct shell profile file.
            bash: macOS, Linux, WSL
            fish: macOS, Linux, WSL
            zsh: macOS, Linux, WSL
            gitbash: Git Bash for Windows
            ps: PowerShell

# EXAMPLES

   *cds* completion --add                   # Add shell completion for cds commands
   *cds* completion --remove                # Remove shell completion for cds commands
   *cds* completion --add --shell bash      # Add shell completion for cds commands and enforce using Bash shell

# ALIASES

   *cds* add completion                     # Add shell completion for cds commands
   *cds* add completion --shell bash        # Add shell completion for cds commands and enforce using Bash shell

`});

async function install(options) {
    await completionSetup.setup(options.add, options);
}

async function completion(_argv, options) {
    if (options.profile) {
        return console.log(completionSetup.resolveScriptPath(options.shell));
    }

    if (options.add || options.remove) {
        await install(options);
        return;
    }

    // workaround to parse complex clis containing -- as part of value,
    // e.g. cds completion --line "cds add --"
    const localArgv = process.argv.slice(3);
    const localOptions = {}
    for (let i = 0; i < localArgv.length; i++) {
        localOptions[localArgv[i].replaceAll('-', '')] = localArgv[++i];
    }

    if (localOptions.curr === undefined || localOptions.prev === undefined || localOptions.line === undefined) {
        throw `Some information is missing. Please run ${bold('cds help completion')} for details on how to call this command.`;
    }

    const shell = localOptions.shell;
    if (!completionSetup.supportedShells.includes(shell)) {
        throw `internal Error: no completion handler found for shell type: ${shell}, supported shells are ${completionSetup.supportedShells.join(', ')}`;
    }

    const currentWord  = localOptions.curr?.trim().replace(/^'|'$/g, '');
    const previousWord = localOptions.prev?.trim().replace(/^'|'$/g, '');
    const line         = localOptions.line?.trim().replace(/^'|'$/g, '');
    const segments     = getSegments(line);
    const cdsCmd       = segments[1] || '';

    const completions = await getCompletions(cdsCmd, previousWord, currentWord, segments);
    reply(completions);
}

// Serializes every command's completion metadata into one map; consumed by the build-time script generator in .github/scripts/completion.
async function buildCompletionMap() {
    const commands = cds.cmds ?? [];
    const commandMap = {};
    for (const cmd of commands) {
        try {
            const obj = cds.load(cmd);
            const raw = await obj.staticCompletions?.() ?? [];
            let positionals = [], optionValues = {}, fileCases = {}, commaCases = {};
            if (Array.isArray(raw)) {
                positionals = raw;
            } else {
                for (const [key, val] of Object.entries(raw)) {
                    const resolved = await val;
                    if (resolved?.type === ':comma') {
                        commaCases[key] = await resolved.values;
                    } else if (isFileSentinel(resolved)) {
                        fileCases[key] = resolved;
                    } else {
                        optionValues[key] = resolved;
                    }
                }
            }
            commandMap[cmd] = {
                options:     (obj.options  ?? []).filter(Boolean),
                flags:       (obj.flags    ?? []).filter(Boolean),
                shortcuts:   (obj.shortcuts ?? []).filter(Boolean),
                positionals,
                optionValues,
                fileCases,
                commaCases,
            };
        } catch (e) { cds.debug?.('completion')?.(`skipping command '${cmd}': ${e?.message ?? e}`); }
    }
    return { commands, shortcuts: cds.Shortcuts, commandMap };
}

// --- Completion engine ---

function reply(values) {
    if (!Array.isArray(values) || values.length === 0) return;

    values = [...new Set(values.filter(e => typeof e === 'string' && e.trim()))];
    values.sort((a, b) => {
        // Files / positionals before flags, then alphabetical within each group.
        const aIsFlag = a.startsWith('-');
        const bIsFlag = b.startsWith('-');
        if (aIsFlag !== bIsFlag) return aIsFlag ? 1 : -1;
        return a.localeCompare(b);
    });

    console.log(values.join('\n'));
}

// Splits a shell command line into tokens, respecting quoted strings and escaped spaces.
function getSegments(line) {
    const cliSplit = /'(.*?)'|"(.*?)"|(\\,|\\ |[^, ])+/gs;
    return line.match(cliSplit).map(s =>
        s.trim()
            .replace(/(\\ )/g, ' ')
            .replace(/^["']|["']$/g, '')
    );
}

// Loads the cds command object for the given name, resolving single-char shortcuts first.
function getCdsCmd(cdsCmd) {
    cdsCmd = cds.Shortcuts?.[cdsCmd] ?? cdsCmd;
    return cds.load(cdsCmd);
}

// Returns all completable flags/options for a command, excluding flags already used on the line.
function getAllOptions(cdsCmdObj, segments) {
    return [
        ...cdsCmdObj.options ?? [],
        ...cdsCmdObj.flags?.filter(o => !segments.includes(o)) ?? [],
    ];
}

async function getCompletions(cdsCmd, previousWord, currentWord, segments) {
    // Returns completions filtered by currentWord prefix, unless commaFiltered is set
    // (comma logic pre-filters its own results to avoid double-filtering).
    let commaFiltered = false;

    const resolveComma = (values, commaStr, partial) => {
        commaFiltered = true;
        const parts      = commaStr.split(',');
        const alreadyUsed = new Set(parts.slice(0, -1).map(s => s.trim()).filter(Boolean));
        const prefix      = parts.slice(0, -1).join(',') + (parts.length > 1 ? ',' : '');
        return values.filter(v => !alreadyUsed.has(v) && v.startsWith(partial)).map(v => prefix + v);
    };

    // Reads the file/dir sentinel for a resolved entry and returns matching paths.
    const resolveSentinel = (sentinel, word) => {
        if (sentinel === DIR())       return completionFs.readdir(word, { files: false });
        if (isFileSentinel(sentinel)) return completionFs.readdir(word, fileRegex(sentinel) ? { fileRegex: fileRegex(sentinel), folders: sentinel.dirs ?? false } : {});
        return null;
    };

    const computeCompletions = async () => {
        // If the cursor is right after 'cds', offer top-level command names.
        if (previousWord === 'cds') {
            if (!currentWord) return cds.cmds;
            const matching = cds.cmds.filter(c => c.startsWith(currentWord));
            if (matching.length) return matching;
            // No command matched the typed prefix — fall through as if typing a compile file arg.
            cdsCmd = 'compile';
            previousWord = 'compile';
        }

        try {
            const cdsCmdObj = getCdsCmd(cdsCmd);

            // Current token starts with '-' → offer flags/options.
            if (currentWord?.startsWith('-')) return getAllOptions(cdsCmdObj, segments);

            const raw = await cdsCmdObj.staticCompletions?.();
            if (raw && !Array.isArray(raw)) {
                // Resolve single-char option shortcuts (e.g. -4 → --for) so we can look up
                // the right key in the staticCompletions map.
                const cmdOptions   = cdsCmdObj.options   ?? [];
                const cmdShortcuts = cdsCmdObj.shortcuts ?? [];
                const shortcutIdx  = cmdShortcuts.indexOf(previousWord);
                const lookupKey    = shortcutIdx !== -1 ? (cmdOptions[shortcutIdx] ?? previousWord) : previousWord;

                // Comma-separated values come in two forms:
                //   inline:          "--add approuter,m"     → prev="--add"      curr="approuter,m"
                //   space-separated: "--add approuter, m"    → prev="approuter," curr="m"
                const isSpaceSeparated = lookupKey.endsWith(',');
                const isInlineComma    = !isSpaceSeparated && currentWord?.includes(',');
                if (isSpaceSeparated || isInlineComma) {
                    // For space-separated form, find the originating option flag in the segments.
                    const optKey = isSpaceSeparated
                        ? cmdOptions.find(o =>
                            segments.includes(o) ||
                            cmdShortcuts.some((s, i) => segments.includes(s) && cmdOptions[i] === o)
                          )
                        : lookupKey;
                    const resolved = optKey ? await raw[optKey] : undefined;
                    if (resolved?.type === ':comma') {
                        const values   = await resolved.values;
                        const commaStr = isSpaceSeparated ? previousWord : currentWord;
                        const partial  = isSpaceSeparated ? (currentWord ?? '') : commaStr.split(',').at(-1);
                        return resolveComma(values, commaStr, partial);
                    }
                }

                // Previous word is a known option → offer its static values or file completions.
                const entry = raw[lookupKey];
                if (entry !== undefined) {
                    const resolved = await entry;
                    if (resolved?.type === ':comma') {
                        const values = await resolved.values;
                        return resolveComma(values, currentWord ?? '', (currentWord ?? '').split(',').at(-1));
                    }
                    return resolveSentinel(resolved, currentWord) ?? resolved;
                }

                // No option matched — check the default positional sentinel.
                const defaultPositional = raw[POSITIONAL_KEY] !== undefined ? await raw[POSITIONAL_KEY] : undefined;
                if (defaultPositional !== undefined) {
                    if (defaultPositional?.type === ':comma') {
                        const values = await defaultPositional.values;
                        return resolveComma(values, currentWord ?? '', (currentWord ?? '').split(',').at(-1));
                    }
                    return resolveSentinel(defaultPositional, currentWord) ?? [];
                }

                // Previous word is a consumed option value (e.g. "approuter" after "--add").
                // Don't offer more positionals — the user has already provided one.
                const allOpts = [...cmdOptions, ...cmdShortcuts, ...(cdsCmdObj.flags ?? [])];
                if (previousWord !== cdsCmd && !allOpts.includes(previousWord)) return [];
            }

            // Array form of staticCompletions → fixed positional list (e.g. cds help <tab>).
            if (Array.isArray(raw) && raw.length) {
                const prevIsOption = cdsCmdObj.options?.includes(previousWord) || cdsCmdObj.shortcuts?.includes(previousWord);
                return prevIsOption ? [] : raw;
            }

            // No staticCompletions — fall back to files + available flags.
            const files = await completionFs.readdir(currentWord);
            const prevIsOption = cdsCmdObj.options?.includes(previousWord) || cdsCmdObj.shortcuts?.includes(previousWord);
            if (!prevIsOption) files.push(...getAllOptions(cdsCmdObj, segments));
            return files;

        } catch {
            return [];
        }
    };

    let completions = await computeCompletions();
    if (currentWord && !commaFiltered) {
        completions = completions.filter(c => c?.startsWith(currentWord));
    }
    return completions;
}
